	}
	result := int64(1)
	for b > 0 {
		if b%2 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		b /= 2
	}
	return result
}

func modInverse(a int64) int64 {
	return modPow(a, mod-2)
}

func main() {
	var n int64
	var k int
	_, err := fmt.Fscanf(os.Stdin, "%d %d", &n, &k)
	if err != nil {
		return
	}

	// Factorize n
	factors := make(map[int64]int)
	temp := n
	for d := int64(2); d*d <= temp; d++ {
		for temp%d == 0 {
			factors[d]++
			temp /= d
		}
	}
	if temp > 1 {
		factors[temp]++
	}

	// For each prime factor p^e, compute the contribution
	// The expected value is multiplicative over prime factors
	// For a prime power p^e, after k steps, the expected value of p^X where X is the exponent
	// is sum_{i=0}^{e} p^i * P(X=i)

	// We need to compute for each prime factor p with exponent e:
	// The probability distribution of the exponent after k steps
	// Starting from exponent e, at each step we pick a divisor uniformly
	// For p^e, the divisors are p^0, p^1, ..., p^e (e+1 divisors)
	// So from state j (exponent j), we transition to state i (0<=i<=j) with probability 1/(j+1)

	// Let dp[step][j] = probability that after 'step' steps, the exponent is j
	// We want sum_{j=0}^{e} p^j * dp[k][j]

	// Since k can be up to 10^4 and e can be up to ~50 (since 2^50 > 10^15),
	// we can do DP for each prime factor

	// Actually, let's think more carefully.
	// The process for each prime factor is independent in terms of the exponent.
	// For prime p with initial exponent e, we have a Markov chain on states 0,1,...,e
	// Transition: from state j, go to state i (0<=i<=j) with probability 1/(j+1)

	// We need to compute the expected value of p^X_k where X_k is the state after k steps
	// E[p^X_k] = sum_{i=0}^{e} p^i * P(X_k = i)

	// Let's do DP for each prime factor
	// dp[j] = probability of being in state j after current number of steps
	// Initially: dp[e] = 1, others 0

	// For each prime factor, compute the contribution to the expected value
	// The total expected value is the product of contributions from each prime factor
	// (because the choices for different primes are independent)

	total := int64(1)

	for p, e := range factors {
		// dp[j] = probability of being in state j
		// Use rational arithmetic or modular arithmetic?
		// We'll use modular arithmetic with modular inverses

		// dp is an array of size e+1
		dp := make([]int64, e+1)
		dp[e] = 1 // probability 1 = 1/1

		for step := 0; step < k; step++ {
			newDp := make([]int64, e+1)
			for j := 0; j <= e; j++ {
				if dp[j] == 0 {
					continue
				}
				// From state j, we can go to any state i where 0 <= i <= j
				// Each with probability 1/(j+1)
				inv := modInverse(int64(j+1))
				for i := 0; i <= j; i++ {
					newDp[i] = (newDp[i] + dp[j]*inv) % mod
				}
			}
			dp = newDp
		}

		// Now compute sum_{i=0}^{e} p^i * dp[i]
		contrib := int64(0)
		pPow := int64(1)
		for i := 0; i <= e; i++ {
			contrib = (contrib + pPow*dp[i]) % mod
