func modPow(a, b int64) int64 {
	a %= mod
	if a < 0 {
		a += mod
	}
	result := int64(1)
	for b > 0 {
		if b%2 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		b /= 2
	}
	return result
}

func modInverse(a int64) int64 {
	return modPow(a, mod-2)
}

func factorize(n int64) map[int64]int {
	factors := make(map[int64]int)
	if n <= 1 {
		return factors
	}
	// Trial division up to sqrt(n)
	for i := int64(2); i*i <= n; i++ {
		for n%i == 0 {
			factors[i]++
			n /= i
		}
	}
	if n > 1 {
		factors[n]++
	}
	return factors
}

func main() {
	input, _ := os.ReadFile("/dev/stdin")
	parts := strings.Fields(string(input))
	if len(parts) < 2 {
		return
	}
	n, _ := strconv.ParseInt(parts[0], 10, 64)
	k, _ := strconv.ParseInt(parts[1], 10, 64)

	factors := factorize(n)

	// For each prime factor p^e, we need to compute the expected value of the exponent after k steps.
	// The exponent starts at e. At each step, if the current exponent is i, we pick a divisor,
	// which means we pick a new exponent j uniformly from {0, 1, ..., i}.
	// So the transition is: from state i, go to state j with probability 1/(i+1) for j in 0..i.
	//
	// Let dp[step][i] = probability that after 'step' steps, the exponent is i.
	// We want E[exponent] = sum_i i * dp[k][i]
	//
	// But k can be up to 10^4 and e can be up to about 50 (since 2^50 > 10^15), so we can do DP on the exponent.
	//
	// Actually, let's think about the expected value directly.
	// Let f(i, t) = expected value of the exponent after t steps starting from exponent i.
	// f(i, 0) = i
	// f(i, t) = (1/(i+1)) * sum_{j=0}^{i} f(j, t-1)
	//
	// We need to compute f(e, k) for each prime factor, then the expected value of the number is the product over all prime factors of (p ^ f(e, k)).
	//
	// Wait, but the expected value of the product is not the product of expected values in general. However, since the choices for different prime factors are independent (the divisor choice decomposes into independent choices for each prime's exponent), the expected value of the product is the product of the expected values.
	//
	// So for each prime p with exponent e, we compute E_p = E[p^X] where X is the random variable for the exponent after k steps.
	// E[p^X] = sum_{i=0}^{e} p^i * Pr(X = i)
	//
	// Let dp[t][i] = probability that after t steps, the exponent is i, starting from e.
	// dp[0][i] = 1 if i == e, else 0.
	// dp[t][i] = sum_{j=i}^{e} dp[t-1][j] / (j+1)
	//
	// Then E_p = sum_{i=0}^{e} p^i * dp[k][i]
	//
	// The answer is the product of E_p over all prime factors, modulo mod.

	// For each prime factor
	answer := int64(1)
	for p, e := range factors {
		// dp[i] = probability that current exponent is i
		// We'll use a slice of size e+1
		dp := make([]int64, e+1)
		dp[e] = 1 // at step 0, exponent is e with probability 1

		for step := 0; step < int(k); step++ {
			newDp := make([]int64, e+1)
			// For each possible new exponent i, newDp[i] = sum_{j=i}^{e} dp[j] / (j+1)
			// We can compute this efficiently with a suffix sum.
			// Let suffix[j] = sum_{m=j}^{e} dp[m] / (m+1)
			// Then newDp[i] = suffix[i]

			// Compute suffix sums
			suffix := make([]int64, e+2)
			for j := e; j >= 0; j-- {
				// dp[j] / (j+1) mod mod
				inv := modInverse(int64(j + 1))
				term := dp[j] * inv % mod
				suffix[j] = (suffix[j+1] + term) % mod
			}
			for i := 0; i <= e; i++ {
				newDp[i] = suffix[i]
			}
			dp = newDp
		}

		// Now compute E_p = sum_{i=0}^{e} p^i * dp[i]
		// p^i mod mod
		pow := int64(1)
		pInt := p % mod
		sum := int64(0)
		for i := 0; i <= e; i++ {
			sum = (sum + pow * dp[i]) % mod
			pow = pow * pInt % mod
		}
		answer = answer * sum % mod
	}

	fmt.Println(answer)
}
