```go
package main

import (
	"fmt"
	"math/big"
	"os"
	"strconv"
	"strings"
)

const mod = 1000000007

func modPow(a, b, m int64) int64 {
	if m == 1 {
		return 0
	}
	a %= m
	if a < 0 {
		a += m
	}
	result := int64(1)
	for b > 0 {
		if b%2 == 1 {
			result = (result * a) % m
		}
		a = (a * a) % m
		b /= 2
	}
	return result
}

func modInverse(a, m int64) int64 {
	return modPow(a, m-2, m)
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func factorize(n int64) map[int64]int {
	factors := make(map[int64]int)
	if n <= 1 {
		return factors
	}
	// Trial division up to sqrt(n)
	d := int64(2)
	for d*d <= n {
		for n%d == 0 {
			factors[d]++
			n /= d
		}
		d++
	}
	if n > 1 {
		factors[n]++
	}
	return factors
}

func main() {
	input, _ := os.ReadFile("/dev/stdin")
	parts := strings.Fields(string(input))
	if len(parts) < 2 {
		return
	}
	n, _ := strconv.ParseInt(parts[0], 10, 64)
	k, _ := strconv.ParseInt(parts[1], 10, 64)

	factors := factorize(n)

	// For each prime factor p^e, we need to compute the expected value of the exponent after k steps.
	// Let E[e] be the expected exponent after k steps starting from exponent e.
	// The transition: from exponent i, we pick a divisor, so the new exponent j is uniformly random from 0 to i.
	// So the transition matrix T has T[i][j] = 1/(i+1) for j=0..i.
	// We want to compute E[exponent] after k steps starting from e.
	// Let f_k(e) = expected exponent after k steps starting from e.
	// f_0(e) = e
	// f_{k+1}(e) = (1/(e+1)) * sum_{j=0}^{e} f_k(j)

	// We can compute this iteratively for each prime factor.
	// Since k can be up to 10^4 and e can be up to ~50 (since 2^50 > 10^15), we can do DP.

	// For each prime factor with exponent e, compute the expected exponent after k steps.
	// Then the expected value of the number is the product over all prime factors of p^(expected exponent).
	// But wait, the expected value of a product is not the product of expected values in general.
	// However, the process for different prime factors is independent! Because when we pick a divisor,
	// the exponent of each prime is chosen independently (uniformly from 0 to current exponent).
	// So the expected value of n after k steps is the product over primes p of p^(E_p),
	// where E_p is the expected exponent of p after k steps.

	// Let's verify: if n = p1^e1 * p2^e2, and we pick a divisor d = p1^j1 * p2^j2 where j1 is uniform in [0,e1] and j2 is uniform in [0,e2],
	// then E[d] = E[p1^j1] * E[p2^j2] because j1 and j2 are independent.
	// And by induction, this holds for all steps.

	// So we compute for each prime factor p with exponent e:
	//   E_p = expected exponent after k steps
	// Then answer = product of modPow(p, E_p, mod) ... but E_p is a rational number.

	// Actually, we need to work with modular arithmetic. Let's think again.
	// The expected value is a rational number P/Q. We need P * Q^{-1} mod mod.

	// Let's define for each prime factor p with initial exponent e:
	//   Let A_k(e) = expected value of p^(exponent) after k steps, starting from exponent e.
	//   A_0(e) = p^e
	//   A_{k+1}(e) = (1/(e+1)) * sum_{j=0}^{e} A_k(j)

	// Then the overall expected value is the product of A_k(e_p) for each prime factor.

	// We can compute A_k(e) for each prime factor using DP.
	// Since e is small (at most ~50), and k is up to 10^4, we can do this.

	// But A_k(e) is a rational number. We need to compute it modulo mod.
	// A_k(e) = (1/(e+1)) * sum_{j=0}^{e} A_{k-1}(j)
	// We can represent A_k(e) as a fraction mod mod.

	// Let's use modular arithmetic. A_k(e) mod mod = modInverse(e+1, mod) * sum_{j=0}^{e} A_{k-1}(j) mod mod

	// Initialize: A_0(e) = p^e mod mod
	// Then iterate k times.

	// For each prime factor, we need to compute A_k(e) where e is the initial exponent.
	// We need A_k(j) for j = 0, 1, ..., e.

	// Let's do this for each prime factor.

	// Collect all exponents we need to handle.
	// For each prime factor p with exponent e, we need to compute a DP table of size (k+1) x (e+1).
	// But k can be 10^4 and e can be ~50, so total operations per prime factor is ~10^4 * 50 = 5*10^5, which is fine.

	// Let's implement this.

	// First, get the list of (prime, exponent) pairs.
	type primeExp struct {
		prime   int64
		exponent int
	}
	var primes []primeExp
	for p, e := range factors {
		primes = append(primes, primeExp{p, e})
	}

	// For each prime factor, compute the expected value of p^(exponent) after k steps.
	// We'll compute a DP table dp[step][exp] = expected value of p^(exp) after 'step' steps, starting from exponent 'exp'.
	// Actually, we want: given we start at exponent e, what is the expected value after k steps?
	// Let f[step][i] = expected value of p^(exponent) after 'step' steps, given current exponent is i.
	// f[0][i] = p^i mod mod
	// f[step+1][i] = modInverse(i+1, mod) * sum_{j=0}^{i} f[step][j] mod mod

	// We need f[k][e] for each prime factor.

	// To save memory, we can use two arrays of size (max_exp+1) and iterate step by step.

