	for d*d <= n {
		count := 0
		for n%d == 0 {
			count++
			n /= d
		}
		if count > 0 {
			factors[d] = count
		}
		d++
	}
	if n > 1 {
		factors[n] = 1
	}
	return factors
}

func main() {
	input, _ := os.ReadFile("/dev/stdin")
	parts := strings.Fields(string(input))

	nStr := parts[0]
	kStr := parts[1]

	n, _ := strconv.ParseInt(nStr, 10, 64)
	k, _ := strconv.Atoi(kStr)

	factors := factorize(n)

	// For each prime power p^a in n, we need to compute the expected value
	// of the exponent after k steps.
	// Let E[a] be the expected exponent starting from exponent a.
	// E[0] = 0
	// For a > 0: E[a] = (1/(a+1)) * sum_{j=0}^{a} E[j]
	// This is because from exponent a, we can transition to any exponent j in [0, a] with equal probability 1/(a+1).

	// We need to compute E[a] for a up to max exponent, but k can be up to 10^4.
	// Actually, we need to track the distribution of exponents after k steps.

	// Let dp[step][e] = probability that after 'step' operations, the exponent is 'e'
	// But e can be up to ~50 (since 2^50 > 10^15), and k up to 10^4.
	// We can do DP over steps and exponents.

	// Max exponent: for n <= 10^15, the max exponent for prime 2 is floor(log2(10^15)) ≈ 49.
	// So exponents are at most around 50.

	maxExp := 0
	for _, exp := range factors {
		if exp > maxExp {
			maxExp = exp
		}
	}

	// dp[e] = probability of having exponent e after current number of steps
	// Initially, dp[maxExp] = 1 for each prime factor's exponent.
	// But we process each prime independently.

	// For a given prime with initial exponent a0, we want to compute:
	// sum_{e=0}^{a0} dp_k[e] * e  where dp_k is the distribution after k steps.

	// Transition: from exponent i, we go to exponent j (0 <= j <= i) with probability 1/(i+1).
	// So new_dp[j] = sum_{i=j}^{maxExp} dp[i] / (i+1)

	// We'll compute for each prime factor separately.

	result := int64(1)

	for p, a0 := range factors {
		// dp[i] = probability of being at exponent i
		// Start: dp[a0] = 1, others 0
		dp := make([]big.Rat, maxExp+1)
		for i := range dp {
			dp[i] = big.Rat{}
		}
		dp[a0].SetInt64(1)

		// Perform k steps
		for step := 0; step < k; step++ {
			newDp := make([]big.Rat, maxExp+1)
			for i := range newDp {
				newDp[i] = big.Rat{}
			}

			// For each current exponent i with probability dp[i],
			// we transition to each j in [0, i] with probability 1/(i+1)
			for i := 0; i <= maxExp; i++ {
				if dp[i].Sign() == 0 {
					continue
				}
				// Probability of going from i to any j in [0,i] is 1/(i+1)
				// So newDp[j] += dp[i] / (i+1) for j = 0, 1, ..., i
				prob := big.Rat{}
				prob.Quo(&dp[i], big.NewRat(int64(i+1), 1))
				for j := 0; j <= i; j++ {
					newDp[j].Add(&newDp[j], &prob)
				}
			}
			dp = newDp
		}

		// Expected exponent = sum_{e=0}^{maxExp} dp[e] * e
		expectedExp := big.Rat{}
		for e := 0; e <= maxExp; e++ {
			if dp[e].Sign() == 0 {
				continue
			}
			term := big.Rat{}
			term.Mul(&dp[e], big.NewRat(int64(e), 1))
			expectedExp.Add(&expectedExp, &term)
		}

		// The contribution to the expected value is p^expectedExp
		// But we need to compute this modulo mod.
		// expectedExp is a rational number P/Q.
		// We need p^(P/Q) mod mod, which is (p^P)^(1/Q) mod mod.
		// This is the Q-th root of p^P mod mod.

		// Actually, we can compute it differently.
		// The expected value contribution from this prime is:
		// sum_{e=0}^{maxExp} dp[e] * p^e
		// = sum_{e=0}^{maxExp} (dp_num[e] / dp_den[e]) * p^e
		// But dp[e] is already a rational.

		// Let's compute sum_{e} dp[e] * p^e as a rational, then convert to mod.

		contrib := big.Rat{}
		for e := 0; e <= maxExp; e++ {
			if dp[e].Sign() == 0 {
				continue
			}
			// p^e
			pe := big.NewInt(1)
			pe.Exp(big.NewInt(p), big.NewInt(int64(e)), nil)
			term := big.Rat{}
			term.Mul(&dp[e], big.NewRat(pe.Int64(), 1))
			contrib.Add(&contrib, &term)
		}

		// Convert contrib (a rational P/Q) to P * Q^{-1} mod mod
		num := contrib.Num()
		den := contrib.Denom()

		numMod := num.Mod(big.NewInt(mod), big.NewInt(mod)).Int64()
		denMod := den.Mod(big.NewInt(mod), big.NewInt(mod)).Int64()

		if numMod < 0 {
			numMod += mod
		}
		if denMod < 0 {
			denMod += mod
		}

		invDen := modInverse(denMod)
		contribMod := numMod * invDen % mod

		result = result * contribMod % mod
	}

	fmt.Println(result)
}
