			factors[d]++
			n /= d
		}
		d++
	}
	if n > 1 {
		factors[n]++
	}
	return factors
}

// Precompute factorials and inverse factorials up to maxK
func precomputeFactorials(maxK int) ([]int64, []int64) {
	fact := make([]int64, maxK+1)
	invFact := make([]int64, maxK+1)
	fact[0] = 1
	for i := 1; i <= maxK; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}
	invFact[maxK] = modInv(fact[maxK])
	for i := maxK - 1; i >= 0; i-- {
		invFact[i] = invFact[i+1] * int64(i+1) % mod
	}
	return fact, invFact
}

// Compute binomial coefficient C(n, r) mod mod
func binom(n, r int, fact, invFact []int64) int64 {
	if r < 0 || r > n {
		return 0
	}
	return fact[n] * invFact[r] % mod * invFact[n-r] % mod
}

func main() {
	input := ""
