package main

import (
	"fmt"
	"math/big"
	"os"
	"strconv"
	"strings"
)

const mod = 1000000007

func modPow(a, b int64) int64 {
	result := int64(1)
	a %= mod
	if a < 0 {
		a += mod
	}
	for b > 0 {
		if b%2 == 1 {
			result = result * a % mod
		}
		a = a * a % mod
		b /= 2
	}
	return result
}

func modInverse(a int64) int64 {
	return modPow(a, mod-2)
}

// Factorize n and return map[prime]exponent
func factorize(n int64) map[int64]int {
	factors := make(map[int64]int)
	if n <= 1 {
		return factors
	}
	// Trial division
	d := int64(2)
	for d*d <= n {
		for n%d == 0 {
			factors[d]++
			n /= d
		}
		d++
	}
	if n > 1 {
		factors[n]++
	}
	return factors
}

func main() {
	input, _ := os.ReadFile("/dev/stdin")
	parts := strings.Fields(string(input))
	if len(parts) < 2 {
		return
	}
	n, _ := strconv.ParseInt(parts[0], 10, 64)
	k, _ := strconv.Atoi(parts[1])

	// Factorize n
	factors := factorize(n)

	// For each prime factor p^e, we need to compute the expected value contribution
	// The expected value of the product is the product of expected values for each prime power
	// due to independence in the divisor selection process

	// For a prime power p^e, after k steps, the expected value of p^X where X is the random exponent
	// We need to compute E[p^X_k] where X_0 = e and at each step, we pick a divisor uniformly at random

	// Let f(e, k) = E[p^X_k] starting from exponent e
	// f(e, 0) = p^e
	// f(e, k) = (1/(e+1)) * sum_{j=0}^{e} f(j, k-1)

	// We can use DP for each prime factor
	// dp[step][exponent] = expected value of p^exponent after 'step' more steps
	// But k can be up to 10^4 and e can be up to ~50 (since 2^50 > 10^15)

	// Actually, let's think differently.
	// Let g(e, k) = E[p^X_k | X_0 = e]
	// g(e, 0) = p^e
	// g(e, k) = (1/(e+1)) * sum_{j=0}^{e} g(j, k-1)

	// We can compute this with DP.
	// For each prime factor with exponent e, we compute g(e, k)
	// Then the answer is the product of g(e_i, k) for all prime factors

	// Let's compute for each prime factor
	answer := int64(1)

	for _, e := range factors {
		// We need to compute g(e, k)
		// dp[step][j] = g(j, step) for j = 0..e
		// dp[0][j] = p^j mod mod
		// dp[step][j] = (1/(j+1)) * sum_{i=0}^{j} dp[step-1][i]

		// We only need the current and previous step
		// prev[j] = g(j, step-1)
		// curr[j] = g(j, step)

		// Base case: step=0
		// prev[j] = p^j mod mod

		// But we don't know p here... wait, we do. Let me restructure.

		// Actually, I need to pass the prime p as well.
		// Let me redo this.
	}

	// Let me restructure: iterate over prime factors with their primes
	// factors is map[prime]exponent
	for p, e := range factors {
		// Compute g(e, k) for this prime p
		// dp[j] = g(j, current_step)
		// Start with step 0: dp[j] = p^j mod mod

		dp := make([]int64, e+1)
		// dp[j] = p^j mod mod
		dp[0] = 1
		for j := 1; j <= e; j++ {
			dp[j] = dp[j-1] * p % mod
		}

		// Now iterate k times
		for step := 0; step < k; step++ {
			newDp := make([]int64, e+1)
			// newDp[j] = (1/(j+1)) * sum_{i=0}^{j} dp[i]
			// Compute prefix sums
			prefix := make([]int64, e+2)
			for j := 0; j <= e; j++ {
				prefix[j+1] = (prefix[j] + dp[j]) % mod
			}
			for j := 0; j <= e; j++ {
				// sum_{i=0}^{j} dp[i] = prefix[j+1]
				// newDp[j] = prefix[j+1] * inv(j+1) mod mod
				inv := modInverse(int64(j + 1))
				newDp[j] = prefix[j+1] * inv % mod
			}
			dp = newDp
		}

		// The answer for this prime factor is dp[e] (starting from exponent e)
		answer = answer * dp[e] % mod
	}

	fmt.Println(answer)
}
